//%BEGIN UDBUHT32_LDNQ_1

`celldefine
module UDBUHT32_LDNQ_1 (Q, G, D);
   output Q;
   input G, D;

   reg viol_0;
     wire viol_x;
   wire delayed_G, delayed_D;

   wire int_res__G;

   /////////////////////////////////////
   //          FUNCTIONALITY          //
   /////////////////////////////////////

`ifdef _fv
   buf inst0  (delayed_G, G);
   buf inst1  (delayed_D, D);
`endif

   not inst2  (int_res__G, delayed_G);

   /////////////////////////////////////
   //             TIMING              //
   /////////////////////////////////////

  `ifndef SNPS_MASK_X_OUT_LATCH
    snps_x_out_latch inst3  (viol_x, viol_0, int_res__G, 1'b1, 1'b1);
 `else
    assign viol_x=1'bz;
  `endif
   `ifdef VIRL_functiononly
        snps_latch #`SNPS_LAT_DELAY  insts0 (Q, viol_x, int_res__G, delayed_D);

   `else

        snps_latch insts0  (Q, viol_x, int_res__G, delayed_D);
   `endif

   `ifdef VIRL_functiononly

   `else

not inst4  (ENABLE_NOT_D, D);
buf inst5  (ENABLE_D, D);

specify
if (G==1'b0) (D +=> Q)=(0, 0);
ifnone (D +=> Q)=(0, 0);
if (D==1'b1) (negedge G => (Q -: 1'b1))=(0, 0);
if (D==1'b0) (negedge G => (Q +: 1'b1))=(0, 0);
(negedge G => (Q : 1'b1))=(0, 0);
$setuphold(posedge G , posedge D , 0 ,0, viol_0, , , delayed_G, delayed_D);
$setuphold(posedge G , negedge D , 0 ,0, viol_0, , , delayed_G, delayed_D);
$width(negedge G &&&  ENABLE_NOT_D==1'b1 , 0 ,0, viol_0);
$width(negedge G &&&  ENABLE_D==1'b1 , 0 ,0, viol_0);
endspecify
   `endif

endmodule
`endcelldefine

//%END UDBUHT32_LDNQ_1

