//%BEGIN UDBUHT32_SYNC2MSFQ_1
`celldefine
module UDBUHT32_SYNC2MSFQ_1 (Q, CK, D, SI, SE);
  input CK, D, SI, SE;
  output Q;
   reg viol_all, viol_0;
    wire xcr_5;
    wire xcr_3;
  wire iq, iq0, d_int;
  `ifdef _fv
    buf inst0  (delayed_CK, CK);
    buf inst1  (delayed_D, D);
    buf inst2  (delayed_SI, SI);
    buf inst3  (delayed_SE, SE);
  `endif


  `ifndef SNPS_MASK_ERR_UDP
    snps_dff_err inst4  (xcr_3, delayed_CK, iq0);
  `else
    assign xcr_3=1'bz;
  `endif
    snps_dff insts0  (iq, viol_all, delayed_CK, iq0, xcr_3);
  `ifndef SNPS_MASK_ERR_UDP
    snps_dff_err inst5  (xcr_5, delayed_CK, d_int);
  `else
    assign xcr_5=1'bz;
  `endif
    snps_dff insts1  (iq0, viol_0, delayed_CK, d_int, xcr_5);
    snps_mux2 inst6  (d_int, delayed_SI, delayed_D, delayed_SE);
  `ifdef VIRL_functiononly
    buf #`SNPS_SEQ_DELAY  instt0 (Q, iq);
  `else
    buf instt0  (Q, iq);
  `endif
  `ifdef VIRL_functiononly
  `else
not inst7  (_net_0, SE);
not inst8  (_net_1, D);
not inst9  (_net_2, SI);
and inst10  (ENABLE_NOT_D_AND_NOT_SE_AND_NOT_SI, _net_0, _net_1, _net_2);
not inst11  (_net_3, SE);
not inst12  (_net_4, D);
and inst13  (ENABLE_NOT_D_AND_NOT_SE_AND_SI, _net_3, _net_4, SI);
not inst14  (_net_5, D);
not inst15  (_net_6, SI);
and inst16  (ENABLE_NOT_D_AND_SE_AND_NOT_SI, SE, _net_5, _net_6);
not inst17  (_net_7, D);
and inst18  (ENABLE_NOT_D_AND_SE_AND_SI, SE, _net_7, SI);
not inst19  (_net_8, SE);
not inst20  (_net_9, SI);
and inst21  (ENABLE_D_AND_NOT_SE_AND_NOT_SI, _net_8, D, _net_9);
not inst22  (_net_10, SE);
and inst23  (ENABLE_D_AND_NOT_SE_AND_SI, _net_10, D, SI);
not inst24  (_net_11, SI);
and inst25  (ENABLE_D_AND_SE_AND_NOT_SI, SE, D, _net_11);
and inst26  (ENABLE_D_AND_SE_AND_SI, SE, D, SI);
not inst27  (_net_12, SI);
not inst28  (_net_13, SE);
and inst29  (ENABLE_NOT_SE_AND_NOT_SI, _net_12, _net_13);
not inst30  (_net_14, SE);
and inst31  (ENABLE_NOT_SE_AND_SI, SI, _net_14);
not inst32  (_net_15, D);
and inst33  (ENABLE_NOT_D_AND_SI, SI, _net_15);
not inst34  (_net_16, SI);
and inst35  (ENABLE_D_AND_NOT_SI, _net_16, D);
not inst36  (_net_17, D);
and inst37  (ENABLE_NOT_D_AND_SE, SE, _net_17);
and inst38  (ENABLE_D_AND_SE, SE, D);

`ifdef FORMALITY 
`else 
   always@(viol_all) begin
      viol_0 = (viol_0 !== viol_all) ? viol_all : ~viol_0;
   end 
`endif 
specify
if (D==1'b0 && SE==1'b0 && SI==1'b0) (posedge CK => (Q : 1'b1))=(0, 0);
if (D==1'b0 && SE==1'b0 && SI==1'b1) (posedge CK => (Q : 1'b1))=(0, 0);
if (D==1'b0 && SE==1'b1 && SI==1'b0) (posedge CK => (Q : 1'b1))=(0, 0);
if (D==1'b0 && SE==1'b1 && SI==1'b1) (posedge CK => (Q : 1'b1))=(0, 0);
if (D==1'b1 && SE==1'b0 && SI==1'b0) (posedge CK => (Q : 1'b1))=(0, 0);
if (D==1'b1 && SE==1'b0 && SI==1'b1) (posedge CK => (Q : 1'b1))=(0, 0);
if (D==1'b1 && SE==1'b1 && SI==1'b0) (posedge CK => (Q : 1'b1))=(0, 0);
